/**
 * JSZip - Lightweight, modern ZIP archive generator for Chrome Extension Manifest V3
 * Compatible with JSZip API: zip.file(name, data), zip.folder(name), zip.generateAsync({type: 'blob'})
 * Native CompressionStream (DEFLATE) + STORE support with standard CRC-32 checksum calculation.
 */
(function (global) {
  "use strict";

  // Pre-computed CRC32 Table
  const CRC32_TABLE = new Uint32Array(256);
  for (let i = 0; i < 256; i++) {
    let c = i;
    for (let k = 0; k < 8; k++) {
      c = (c & 1) ? (0xEDB88320 ^ (c >>> 1)) : (c >>> 1);
    }
    CRC32_TABLE[i] = c;
  }

  function crc32(uint8Array) {
    let crc = -1;
    for (let i = 0; i < uint8Array.length; i++) {
      crc = (crc >>> 8) ^ CRC32_TABLE[(crc ^ uint8Array[i]) & 0xFF];
    }
    return (crc ^ (-1)) >>> 0;
  }

  function dosDateTime(date) {
    const d = date || new Date();
    const time = ((d.getHours() & 0x1F) << 11) | ((d.getMinutes() & 0x3F) << 5) | ((Math.floor(d.getSeconds() / 2)) & 0x1F);
    const dateNum = (((d.getFullYear() - 1980) & 0x7F) << 9) | (((d.getMonth() + 1) & 0x0F) << 5) | (d.getDate() & 0x1F);
    return { time: time & 0xFFFF, date: dateNum & 0xFFFF };
  }

  async function toUint8Array(data) {
    if (!data) return new Uint8Array(0);
    if (data instanceof Uint8Array) return data;
    if (data instanceof ArrayBuffer) return new Uint8Array(data);
    if (ArrayBuffer.isView(data)) return new Uint8Array(data.buffer, data.byteOffset, data.byteLength);
    if (data instanceof Blob) {
      const buffer = await data.arrayBuffer();
      return new Uint8Array(buffer);
    }
    if (typeof data === "string") {
      if (data.startsWith("data:")) {
        const base64Index = data.indexOf(";base64,");
        if (base64Index !== -1) {
          const b64 = data.substring(base64Index + 8);
          const binaryStr = atob(b64);
          const len = binaryStr.length;
          const bytes = new Uint8Array(len);
          for (let i = 0; i < len; i++) {
            bytes[i] = binaryStr.charCodeAt(i);
          }
          return bytes;
        }
      }
      return new TextEncoder().encode(data);
    }
    return new Uint8Array(0);
  }

  async function compressDeflate(uint8Array) {
    if (typeof CompressionStream !== "undefined") {
      try {
        const cs = new CompressionStream("deflate-raw");
        const writer = cs.writable.getWriter();
        writer.write(uint8Array);
        writer.close();
        const response = new Response(cs.readable);
        const buffer = await response.arrayBuffer();
        return new Uint8Array(buffer);
      } catch (e) {
        // Fallback to STORE if deflate-raw is unsupported
      }
    }
    return null;
  }

  class JSZip {
    constructor() {
      this.files = {};
    }

    file(name, data, options = {}) {
      if (data === null || data === undefined) {
        return this.files[name] || null;
      }
      // Normalize slashes
      const cleanName = name.replace(/\\/g, "/").replace(/^\/+/, "");
      this.files[cleanName] = {
        name: cleanName,
        data: data,
        options: options,
        date: options.date || new Date()
      };
      return this;
    }

    folder(name) {
      const cleanName = name.replace(/\\/g, "/").replace(/^\/+/, "").replace(/\/+$/, "") + "/";
      this.files[cleanName] = {
        name: cleanName,
        data: new Uint8Array(0),
        options: { dir: true },
        date: new Date()
      };
      const subZip = new JSZip();
      subZip.files = this.files;
      return subZip;
    }

    async generateAsync(options = {}, onUpdate) {
      const type = options.type || "blob";
      const compression = (options.compression || "DEFLATE").toUpperCase();
      const entries = Object.keys(this.files);
      const totalEntries = entries.length;

      const localHeaders = [];
      const centralHeaders = [];
      let currentOffset = 0;

      for (let i = 0; i < totalEntries; i++) {
        const fileName = entries[i];
        const entry = this.files[fileName];
        const rawBytes = await toUint8Array(entry.data);
        const checksum = crc32(rawBytes);
        const { time, date } = dosDateTime(entry.date);
        const isDir = !!(entry.options && entry.options.dir) || fileName.endsWith("/");

        let compressedBytes = null;
        let compressionMethod = 0; // 0 = STORE

        if (!isDir && compression === "DEFLATE" && rawBytes.length > 0) {
          compressedBytes = await compressDeflate(rawBytes);
          if (compressedBytes && compressedBytes.length < rawBytes.length) {
            compressionMethod = 8; // 8 = DEFLATE
          } else {
            compressedBytes = rawBytes;
            compressionMethod = 0;
          }
        } else {
          compressedBytes = rawBytes;
          compressionMethod = 0;
        }

        const fileNameBytes = new TextEncoder().encode(fileName);
        const uncompressedSize = rawBytes.length;
        const compressedSize = compressedBytes.length;

        // Local Header (30 bytes + filename)
        const localHeader = new Uint8Array(30 + fileNameBytes.length + compressedSize);
        const viewLH = new DataView(localHeader.buffer);

        viewLH.setUint32(0, 0x04034b50, true); // Signature
        viewLH.setUint16(4, 20, true);         // Version needed
        viewLH.setUint16(6, 0, true);          // General purpose bit flag
        viewLH.setUint16(8, compressionMethod, true); // Compression method
        viewLH.setUint16(10, time, true);       // Mod time
        viewLH.setUint16(12, date, true);       // Mod date
        viewLH.setUint32(14, checksum, true);   // CRC-32
        viewLH.setUint32(18, compressedSize, true); // Compressed size
        viewLH.setUint32(22, uncompressedSize, true); // Uncompressed size
        viewLH.setUint16(26, fileNameBytes.length, true); // Filename length
        viewLH.setUint16(28, 0, true);          // Extra field length

        localHeader.set(fileNameBytes, 30);
        localHeader.set(compressedBytes, 30 + fileNameBytes.length);

        localHeaders.push(localHeader);

        // Central Directory Header (46 bytes + filename)
        const centralHeader = new Uint8Array(46 + fileNameBytes.length);
        const viewCH = new DataView(centralHeader.buffer);

        viewCH.setUint32(0, 0x02014b50, true); // Signature
        viewCH.setUint16(4, 20, true);         // Version made by
        viewCH.setUint16(6, 20, true);         // Version needed
        viewCH.setUint16(8, 0, true);          // General purpose bit flag
        viewCH.setUint16(10, compressionMethod, true); // Compression method
        viewCH.setUint16(12, time, true);       // Mod time
        viewCH.setUint16(14, date, true);       // Mod date
        viewCH.setUint32(16, checksum, true);   // CRC-32
        viewCH.setUint32(20, compressedSize, true); // Compressed size
        viewCH.setUint32(24, uncompressedSize, true); // Uncompressed size
        viewCH.setUint16(28, fileNameBytes.length, true); // Filename length
        viewCH.setUint16(30, 0, true);          // Extra field length
        viewCH.setUint16(32, 0, true);          // File comment length
        viewCH.setUint16(34, 0, true);          // Disk number start
        viewCH.setUint16(36, 0, true);          // Internal file attributes
        viewCH.setUint32(38, isDir ? 0x10 : 0x20, true); // External file attributes
        viewCH.setUint32(42, currentOffset, true); // Relative offset of local header

        centralHeader.set(fileNameBytes, 46);
        centralHeaders.push(centralHeader);

        currentOffset += localHeader.length;

        if (typeof onUpdate === "function") {
          onUpdate({ percent: Math.round(((i + 1) / totalEntries) * 100), currentFile: fileName });
        }
      }

      let centralDirectorySize = 0;
      for (const ch of centralHeaders) centralDirectorySize += ch.length;

      // End of Central Directory Record (22 bytes)
      const eocd = new Uint8Array(22);
      const viewEOCD = new DataView(eocd.buffer);

      viewEOCD.setUint32(0, 0x06054b50, true); // Signature
      viewEOCD.setUint16(4, 0, true);          // Disk number
      viewEOCD.setUint16(6, 0, true);          // Start disk
      viewEOCD.setUint16(8, totalEntries, true); // Total entries on disk
      viewEOCD.setUint16(10, totalEntries, true); // Total entries
      viewEOCD.setUint32(12, centralDirectorySize, true); // Size of central dir
      viewEOCD.setUint32(16, currentOffset, true); // Offset of central dir
      viewEOCD.setUint16(20, 0, true);          // Comment length

      // Combine parts into final Uint8Array
      const totalSize = currentOffset + centralDirectorySize + 22;
      const finalZipBytes = new Uint8Array(totalSize);
      let writePos = 0;

      for (const lh of localHeaders) {
        finalZipBytes.set(lh, writePos);
        writePos += lh.length;
      }
      for (const ch of centralHeaders) {
        finalZipBytes.set(ch, writePos);
        writePos += ch.length;
      }
      finalZipBytes.set(eocd, writePos);

      if (type === "uint8array") return finalZipBytes;
      if (type === "arraybuffer") return finalZipBytes.buffer;
      if (type === "base64") {
        let binary = "";
        const len = finalZipBytes.byteLength;
        for (let i = 0; i < len; i++) {
          binary += String.fromCharCode(finalZipBytes[i]);
        }
        return btoa(binary);
      }

      // Default: blob
      return new Blob([finalZipBytes], { type: "application/zip" });
    }
  }

  global.JSZip = JSZip;
})(typeof self !== "undefined" ? self : window);
